/**
 * Image assets, lifted verbatim from the approved mockup
 * (`client/public/mockup.html`). Data URIs so there is nothing to fetch and
 * nothing to 404 — the app renders identically offline and in a screenshot run.
 *
 * CAN is the beer-can mark: it is the header logo AND every shotgun icon.
 * A shotgun is a can; that is the whole visual rule (docs/DESIGN.md).
 *
 * AVATARS are the 8 footballs. Do not add a 9th without reading `avatarFor`.
 */

/** The can mark — header logo and shotgun unit icon. */
export const CAN = 'data:image/png;base64,';

/** The 8 avatar footballs, keyed a..h exactly as in the mockup. */
export const AVATARS = {
  a: 'data:image/jpeg;base64,',
  b: 'data:image/jpeg;base64,',
  c: 'data:image/jpeg;base64,',
  d: 'data:image/jpeg;base64,',
  e: 'data:image/jpeg;base64,',
  f: 'data:image/jpeg;base64,',
  g: 'data:image/jpeg;base64,',
  h: 'data:image/jpeg;base64,',
};

export const AVATAR_KEYS = Object.keys(AVATARS);

/**
 * Pick a player's avatar from their NAME, deterministically.
 *
 * The same person is the same football in every game they ever play, which is
 * what makes the grid readable at a glance across a season — you learn to hunt
 * for a shape, not read a word.
 *
 * `taken` lets the caller keep a room collision-free: with <= 8 players nobody
 * shares a football. Past 8 they must, and the hash order decides who doubles up.
 *
 * The hash is FNV-1a, chosen only because it is short, stable, and has no
 * dependencies. It must never change: changing it reshuffles everyone's avatar.
 */
export const avatarKeyFor = (name, taken = []) => {
  const text = String(name == null ? '' : name);
  let hash = 0x811c9dc5;
  for (let i = 0; i < text.length; i += 1) {
    hash ^= text.charCodeAt(i);
    hash = Math.imul(hash, 0x01000193) >>> 0;
  }
  const start = hash % AVATAR_KEYS.length;
  for (let step = 0; step < AVATAR_KEYS.length; step += 1) {
    const key = AVATAR_KEYS[(start + step) % AVATAR_KEYS.length];
    if (!taken.includes(key)) return key;
  }
  return AVATAR_KEYS[start];
};

/** Resolve a whole roster at once, so collisions are handled consistently. */
export const avatarMapFor = (names = []) => {
  const taken = [];
  const map = {};
  names.forEach((name) => {
    const key = avatarKeyFor(name, taken);
    taken.push(key);
    map[name] = AVATARS[key];
  });
  return map;
};

export const avatarFor = (name, taken = []) => AVATARS[avatarKeyFor(name, taken)];
